<!doctype html><html><head><meta charset="utf-8"><title>{{ $quote->number }}</title><link rel="stylesheet" href="{{ asset('css/cleanflow.css') }}"></head><body class="print"><main><div class="print-head"><div><b class="brand">✦ {{ $business->name }}</b><p>{{ $business->email }}<br>{{ $business->phone }}</p></div><div><h1>Quote</h1><p>{{ $quote->number }}<br>Expires {{ $quote->expires_at?->format('j M Y') }}</p></div></div><p><b>Prepared for</b><br>{{ $quote->customer->name }}<br>{{ $quote->customer->address }}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>@foreach($quote->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>{{ $quote->currency }} {{ number_format($item->unit_price,2) }}</td><td>{{ $quote->currency }} {{ number_format($item->total,2) }}</td></tr>@endforeach</tbody></table><div class="print-total">Total: {{ $quote->currency }} {{ number_format($quote->total,2) }}</div><h3>Notes</h3><p>{{ $quote->notes }}</p><h3>Terms</h3><p>{!! nl2br(e($quote->terms)) !!}</p></main><script>window.onload=()=>window.print()</script></body></html>
